    m, n = len(grid), n_cols

    # ----- main algorithm -----
    islands = 0
    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(m):
        for c in range(n):
            if grid[r][c] != '1':
                continue

            # New island found
            islands += 1
            stack = [(r, c)]

            while stack:
                x, y = stack.pop()
                if grid[x][y] != '1':
                    continue
                # mark visited
                grid[x][y] = '0'
                # push neighbours
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == '1':
                        stack.append((nx, ny))

    return islands

